// Three actions in this subflow. Outputs: list | detail | acknowledge | unknown
const action = msg._req && msg._req.action;
if (action === 'alerts.list')        return [msg, null, null, null];
if (action === 'alerts.detail')      return [null, msg, null, null];
if (action === 'alerts.acknowledge') return [null, null, msg, null];
msg._result = { ok: false, errors: { action: 'alerts: unknown action: ' + action } };
return [null, null, null, msg];

const ring = global.get('alerts') || [];
// Newest first, bounded to 500.
const out = [...ring].slice(-500).reverse();
msg._result = { ok: true, data: { alerts: out, count: out.length } };
return msg;

const id = msg._req && msg._req.payload && msg._req.payload.id;
if (!id) {
    msg._result = { ok: false, errors: { fields: { id: 'required' } } };
    return msg;
}
const ring = global.get('alerts') || [];
const alert = ring.find((a) => a && a.id === id);
if (!alert) {
    msg._result = { ok: false, errors: { action: 'alert not found' } };
    return msg;
}
msg._result = { ok: true, data: { alert } };
return msg;

const id = msg._req && msg._req.payload && msg._req.payload.id;
if (!id) {
    msg._result = { ok: false, errors: { fields: { id: 'required' } } };
    return msg;
}
const ring = global.get('alerts') || [];
const alert = ring.find((a) => a && a.id === id);
if (!alert) {
    msg._result = { ok: false, errors: { action: 'alert not found' } };
    return msg;
}
alert.status = 'acknowledged';
alert.acknowledgedAt = new Date().toISOString();
global.set('alerts', ring);
msg._result = { ok: true, data: { alert } };
return msg;

// 1. Append to ring buffer.
const ring = global.get('alerts') || [];
const err = msg.error || {};
const entry = {
    id: 'err-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    source: (err.source && err.source.id) || 'unknown',
    category: 'runtime',
    severity: 'warning',
    timestamp: new Date().toISOString(),
    status: 'open',
    message: String((err && err.message) || msg.payload || 'unknown error').slice(0, 500)
};
ring.push(entry);
while (ring.length > 500) ring.shift();
global.set('alerts', ring);

// 2. Broadcast a FAP §9 event envelope to all connected UIBUILDER clients.
//    No _socketId means merge-session-send leaves _uib unset, so UIBUILDER
//    fan-outs the message to every connected client. The reducer's
//    reduceEvent('alerts.new') unshifts entry onto state.model.alerts.
const broadcast = {
    payload: {
        type: 'event',
        event: 'alerts.new',
        data: { alert: entry }
    }
};
return [null, broadcast];
